test:
fs = InMemoryUnixFileSystem()
for operation in (lambda: fs.touch('/'), lambda: fs.touch('/missing/file')):
    try:
        operation()
        assert False, 'expected ValueError'
    except ValueError:
        pass

fs.mkdir('/dir')
try:
    fs.touch('/dir')
    assert False, 'expected ValueError'
except ValueError:
    pass

fs.touch('/file')
try:
    fs.mkdir('/file')
    assert False, 'expected ValueError'
except ValueError:
    pass
